#include <Arduino.h>
#include <DHT.h>
#include <TM1637Display.h>
#include <math.h>

DHT sensor(7, DHT11);
TM1637Display display(4, 5);
float temperatureC = NAN;
unsigned long lastRead = 0;
bool sampled = false;
bool wasAlarm = false;
unsigned long alarmStart = 0;

void setup() {
  pinMode(A0, INPUT);
  pinMode(13, OUTPUT);
  pinMode(6, OUTPUT);
  digitalWrite(13, LOW);
  noTone(6);
  sensor.begin();
  display.setBrightness(7);
  display.clear();
}

void loop() {
  unsigned long now = millis();
  if (!sampled || now - lastRead >= 2000UL) {
    sampled = true;
    lastRead = now;
    float reading = sensor.readTemperature();
    if (!isnan(reading)) temperatureC = reading;
  }

  int threshold = (int)((long)analogRead(A0) * 50L / 1023L);
  bool alarm = !isnan(temperatureC) && temperatureC > threshold;
  if (alarm && !wasAlarm) alarmStart = now;
  digitalWrite(13, alarm ? HIGH : LOW);
  if (alarm && ((now - alarmStart) % 1000UL < 500UL)) {
    tone(6, 2000);
  } else {
    noTone(6);
  }
  wasAlarm = alarm;

  if ((now / 1000UL) % 2UL == 0) {
    if (!isnan(temperatureC)) {
      display.showNumberDec((int)round(temperatureC), false);
    } else {
      const uint8_t missing[4] = {0x40, 0x40, 0x40, 0x40};
      display.setSegments(missing);
    }
  } else {
    display.showNumberDec(threshold, false);
  }
  delay(20);
}
